import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { mix, smoothstep, uv, vec3, uniform, time } from 'three/tsl';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group, Mesh, PlaneGeometry, BoxGeometry, Color,
    DirectionalLight, AmbientLight,
  } = THREE;

  const root = new Group();
  root.name = 'collection-row';

  const colors = config.intent?.visualSpec?.colors ?? {};
  const ink     = new Color(colors.ink     ?? '#16161d');
  const paper   = new Color(colors.paper   ?? '#e8ecf2');
  const accent  = new Color(colors.accent  ?? '#ff2a38');
  const surface = new Color(colors.surface ?? '#0b0b10');

  // Row geometry — wide horizontal slab sized to fill hub frame width.
  const W = 6.6, H = 0.62;

  // ── Main row panel (brushed-metal PBR) ─────────────────────
  const rowMat = new MeshStandardNodeMaterial({
    color: 0xffffff,
    metalness: 0.5,
    roughness: 0.62,
    transparent: true,
    opacity: 1.0,
  });
  // Tone the metal toward ink so it reads "engineered" not "white panel".
  rowMat.colorNode = mix(vec3(0xffffff), vec3(ink).bgr, uniform(0.32));
  const row = new Mesh(new PlaneGeometry(W, H), rowMat);
  row.position.set(0, 0, 0);
  root.add(row);

  // Brushed-metal texture (async via cached loader).
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.anisotropy = 8;
      tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
      rowMat.map = tex;
      rowMat.needsUpdate = true;
    });
  }

  // ── Subtle bottom divider (ink with accent bloom on hover) ─
  const dividerMat = new MeshBasicNodeMaterial({
    color: ink.clone(),
    transparent: true,
    opacity: 0.55,
  });
  const divider = new Mesh(new PlaneGeometry(W, 0.012), dividerMat);
  divider.position.set(0, -H / 2 - 0.018, 0.0015);
  root.add(divider);

  // Accent bloom over divider on hover (subtler than a full edge).
  const bloomMat = new MeshBasicNodeMaterial({
    color: accent.clone(),
    transparent: true,
    opacity: 0.0,
    depthWrite: false,
  });
  const bloom = new Mesh(new PlaneGeometry(W, 0.04), bloomMat);
  bloom.position.set(0, -H / 2 - 0.018, 0.002);
  root.add(bloom);

  // ── Accent edge strip on the left rail (focus indicator) ───
  const edgeMat = new MeshBasicNodeMaterial({
    color: accent.clone(),
    transparent: true,
    opacity: 0.0,
  });
  const edge = new Mesh(new PlaneGeometry(0.022, H * 0.86), edgeMat);
  edge.position.set(-W / 2 + 0.014, 0, 0.002);
  root.add(edge);

  // ── Engineered index notch (left machined keyway) ─────────
  const keywayMat = new MeshStandardNodeMaterial({
    color: paper.clone().multiplyScalar(0.18),
    metalness: 0.55,
    roughness: 0.5,
    transparent: true,
    opacity: 0.9,
  });
  const keyway = new Mesh(new BoxGeometry(0.05, H * 0.5, 0.03), keywayMat);
  keyway.position.set(-W / 2 + 0.32, 0, 0.012);
  root.add(keyway);

  // ── Right rail terminal dot (accent, dim baseline) ───────
  const dotMat = new MeshBasicNodeMaterial({
    color: accent.clone(),
    transparent: true,
    opacity: 0.25,
  });
  const dot = new Mesh(new PlaneGeometry(0.05, 0.05), dotMat);
  dot.position.set(W / 2 - 0.34, 0, 0.002);
  root.add(dot);

  // ── Contact shadow under the row ─────────────────────────
  const shadowMat = new MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.42,
    depthWrite: false,
  });
  const shadow = new Mesh(new PlaneGeometry(W * 1.04, 0.16), shadowMat);
  shadow.position.set(0, -H / 2 - 0.075, -0.02);
  root.add(shadow);

  // ── Rim accent light node-local (white-subject key ceiling) ─
  // Scene supplies ambient 0.6 + key 1.2; we only add a rim accent ≤1.5.
  const rim = new DirectionalLight(accent.clone().lerp(new Color(0xffffff), 0.4), 0.85);
  rim.position.set(-3.2, 0.6, -2.5);
  root.add(rim);

  // ── Interaction state ─────────────────────────────────────
  const baseY = 0;
  let liftActive = false;

  const handlers = {
    pointerenter: () => {
      if (liftActive) return;
      liftActive = true;
      // rise-in preset (subtle, 0.15 scene units)
      gsap.killTweensOf(root.position);
      gsap.to(root.position, {
        y: baseY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
      // accent edge + divider bloom reveal
      gsap.killTweensOf(edgeMat);
      gsap.to(edgeMat, { opacity: 1.0, duration: 0.4, ease: 'power2.out' });
      gsap.killTweensOf(bloomMat);
      gsap.to(bloomMat, { opacity: 0.7, duration: 0.4, ease: 'power2.out' });
      gsap.killTweensOf(dotMat);
      gsap.to(dotMat, { opacity: 1.0, duration: 0.4, ease: 'power2.out' });
    },
    pointerleave: () => {
      liftActive = false;
      gsap.killTweensOf(root.position);
      gsap.to(root.position, {
        y: baseY,
        duration: 0.5,
        ease: 'power2.out',
      });
      gsap.killTweensOf(edgeMat);
      gsap.to(edgeMat, { opacity: 0.0, duration: 0.35, ease: 'power2.out' });
      gsap.killTweensOf(bloomMat);
      gsap.to(bloomMat, { opacity: 0.0, duration: 0.35, ease: 'power2.out' });
      gsap.killTweensOf(dotMat);
      gsap.to(dotMat, { opacity: 0.25, duration: 0.35, ease: 'power2.out' });
    },
    click: () => {
      // press-down + weighted-settle release
      gsap.killTweensOf(root.scale);
      const tl = gsap.timeline();
      tl.to(root.scale, {
        x: 0.97, y: 0.97, z: 0.97,
        duration: 0.12,
        ease: 'back.out(2)',
      });
      tl.to(root.scale, {
        x: 1.0, y: 1.0, z: 1.0,
        duration: 0.9,
        ease: 'power4.out',
      });
      ctx.emit('hub-collection.select', { source: 'collection-row' });
    },
    focus: () => {
      gsap.killTweensOf(edgeMat);
      gsap.to(edgeMat, { opacity: 1.0, duration: 0.3, ease: 'power2.out' });
      gsap.killTweensOf(bloomMat);
      gsap.to(bloomMat, { opacity: 0.5, duration: 0.3, ease: 'power2.out' });
    },
    blur: () => {
      gsap.killTweensOf(edgeMat);
      gsap.to(edgeMat, { opacity: 0.0, duration: 0.3, ease: 'power2.out' });
      gsap.killTweensOf(bloomMat);
      gsap.to(bloomMat, { opacity: 0.0, duration: 0.3, ease: 'power2.out' });
    },
  };

  root.userData.handlers = handlers;

  root.userData.cleanup = () => {
    gsap.killTweensOf(root.position);
    gsap.killTweensOf(root.scale);
    gsap.killTweensOf(edgeMat);
    gsap.killTweensOf(bloomMat);
    gsap.killTweensOf(dotMat);
    [rowMat, dividerMat, bloomMat, edgeMat, keywayMat, dotMat, shadowMat]
      .forEach((m) => { try { m.dispose(); } catch (e) {} });
    [row, divider, bloom, edge, keyway, dot, shadow]
      .forEach((o) => { try { o.geometry.dispose(); } catch (e) {} });
  };

  return root;
}
